import {connectCube,validFacelets,forgetLastDevice} from './connection.js?v=15';
const $=id=>document.getElementById(id), solved=new Cube().asString(), fa=new Intl.NumberFormat('fa');
let connectionPaused=false;let connectAbort=null,connectAttempt=0,connectStage=null;let conn=null,subscription=null,cube=null,armed=false,running=false,start=0,moveCount=0,log=[],busy=false;
let records=[];try{const a=JSON.parse(localStorage.getItem('gan-fa-solves')||'[]');if(Array.isArray(a))records=a.filter(r=>Number.isFinite(r.seconds)&&r.seconds>0&&Number.isFinite(r.moves)&&typeof r.date==='string');}catch{}
function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error)}
function save(){try{localStorage.setItem('gan-fa-solves',JSON.stringify(records))}catch{notice('مرورگر اجازه ذخیره رکوردها را نداد. خروجی بگیر.',true)}renderRecords()}
function renderRecords(){ $('count').textContent=fa.format(records.length);$('best').textContent=records.length?Math.min(...records.map(r=>r.seconds)).toFixed(2):'—';$('records').replaceChildren();if(!records.length){const p=document.createElement('p');p.className='empty';p.textContent='اولین حل تو هنوز ثبت نشده است.';$('records').append(p)}for(const r of records.slice(-12).reverse()){const el=document.createElement('div');el.className='record';const date=document.createElement('span');date.textContent=new Date(r.date).toLocaleDateString('fa-IR');const time=document.createElement('strong');time.dir='ltr';time.textContent=r.seconds.toFixed(2)+' s';const moves=document.createElement('span');moves.textContent=fa.format(r.moves)+' حرکت';el.append(date,time,moves);$('records').append(el)}}
const positions={U:[2,1],L:[1,2],F:[2,2],R:[3,2],B:[4,2],D:[2,3]},colors={U:'#f7f5ed',R:'#e65a55',F:'#44ad7e',D:'#f5d75a',L:'#f39a51',B:'#5594dc'};
function draw(){const s=cube?.asString()||solved;$('net').replaceChildren();[...'URFDLB'].forEach((f,i)=>{const el=document.createElement('div');el.className='face';el.style.gridColumn=positions[f][0];el.style.gridRow=positions[f][1];el.title=f;for(let j=0;j<9;j++){const t=document.createElement('span');t.className='sticker';t.style.background=colors[s[i*9+j]]||'#999';el.append(t)}$('net').append(el)});$('net').style.opacity=cube?'1':'.35'}
function controls(){const connected=!!conn;$('forget').disabled=busy;$('robot').disabled=busy;$('connect').disabled=connected||busy;$('disconnect').disabled=!connected&&!busy;$('sync').disabled=!connected||running||connectionPaused;$('reset').disabled=!connected||running||armed||connectionPaused;$('arm').disabled=!connected||!cube||running||armed||connectionPaused;$('cancel').hidden=!running&&!armed;$('connection').textContent=connectionPaused?'در حال بازیابی اتصال':connected?conn.deviceName:'روبیک متصل نیست';$('phase').textContent=connectionPaused?'در حال بازیابی':running?'در حال حل':armed?'منتظر اولین حرکت':connected?'آماده تمرین':'آماده اتصال'}
function cancel(){running=false;armed=false;controls()}
function event(e){if(e.type==='MOTION_TEST_PROGRESS'){$('motiontest').textContent='نمونه '+fa.format(e.sample+1)+' از '+fa.format(e.total);$('motionresult').value='آزمایش در حال اجراست؛ '+fa.format(e.sample+1)+' نمونه از '+fa.format(e.total)+' دریافت شد. چرخاندن وجه راست را ادامه بده.';return}if(e.type==='CONNECTION_DIAGNOSTIC'){$('diagnostic').textContent='نسخه اتصال ۱۵ | علت: '+e.reason+' | مسیر: '+(e.mode||'نامشخص')+' | مرحله بازیابی: '+(e.recoveryStage||'ندارد')+' | تلاش بازیابی: '+(e.reconnectAttempts||0)+' | مهلت‌های تمام‌شده: '+(e.timeouts||0)+' | آخرین توقف: '+JSON.stringify(e.lastTimeout||null)+' | آزمایش حرکت: '+JSON.stringify(e.motionProbe?.summary||null)+' | طول پیام‌ها: '+JSON.stringify(e.readLengths||{})+' | قطع واقعی: '+e.linkLosses+' | خطای خواندن: '+e.readErrors+' | بازیابی: '+e.reconnections+' | مدت آخرین اتصال: '+(e.lastSessionMs==null?'نامشخص':(e.lastSessionMs/1000).toFixed(2)+' ثانیه')+' | آخرین خطای خواندن: '+JSON.stringify(e.lastReadError)+' | نتیجه آزمایش بدون خواندن: '+JSON.stringify(e.lastNoReadTest||null)+' | خطای پردازش: '+(e.lastError||'ندارد')+' | روند: '+JSON.stringify(e.trace);return}if(e.type==='CONNECTION_PAUSED'){connectionPaused=true;cancel();notice(e.reason==='motion-test'?'آزمایش حرکت: وجه راست را هر ثانیه ۹۰ درجه بچرخان؛ یک بار رفت، یک بار برگشت.':e.reason==='link-test'?'آزمایش ۶۰ ثانیه‌ای بدون خواندن داده در حال اجراست؛ روبیک را ثابت بگذار.':'ارتباط در حال بازیابی خودکار است.');return}if(e.type==='CONNECTION_RESUMED'){connectionPaused=false;controls();notice('ارتباط دوباره برقرار شد و وضعیت مکعب خوانده شد.');return}if(e.type==='SYNC_LOST'){cancel();notice('همگامی حرکت‌ها از دست رفت؛ حل جاری لغو شد. وضعیت مکعب را بررسی کن.',true);return}if(e.type==='DISCONNECT'){connectionPaused=false;cancel();subscription=null;conn=null;cube=null;draw();controls();notice(e.reason==='recovery-exhausted'?'بازیابی پس از ۵ تلاش کامل نشد. روبیک را بیدار کن و «اتصال روبیک» را بزن؛ جزئیات در گزارش ثبت شده است.':'اتصال روبیک قطع شد. دوباره وصل کن.',true);return}if(e.type==='BATTERY')$('battery').textContent='باتری: '+fa.format(e.batteryLevel)+'٪';if(e.type==='FACELETS'){if(validFacelets(e)){cube=Cube.fromString(e.facelets);draw();controls()}}if(e.type==='MOVE'){if(!cube){notice('ابتدا وضعیت روبیک را بخوان یا روبیک حل‌شده را همگام کن.',true);return}try{cube.move(e.move)}catch{cancel();cube=null;draw();controls();notice('حرکت نامعتبر دریافت شد؛ وضعیت را دوباره بخوان.',true);return}log.push(e.move);log=log.slice(-24);$('moveLog').textContent=log.join(' ');draw();if(armed){armed=false;running=true;start=performance.now();moveCount=0;controls()}if(running){moveCount++;$('moves').textContent=fa.format(moveCount);if(cube.asString()===solved){const seconds=(performance.now()-start)/1000;cancel();$('clock').textContent=seconds.toFixed(2);if(seconds>0)records.push({seconds,moves:moveCount,date:new Date().toISOString()});save();notice('حل ثبت شد. برای حل بعدی، دوباره روبیک را به‌هم بریز.')}}}}
$('connect').onclick=async()=>{if(busy||conn)return;if(!navigator.bluetooth){notice('لینک را مستقیماً در Chrome روی مک یا کامپیوتر باز کن.',true);return}const mac=$('mac').value.trim();if(mac&&!/^([0-9a-f]{2}:){5}[0-9a-f]{2}$/i.test(mac)){notice('آدرس دستی معتبر نیست؛ برای شناسایی خودکار، کادر را خالی بگذار.',true);return}busy=true;const attempt=++connectAttempt,controller=new AbortController();connectAbort=controller;connectStage='select';$('reloadconnection').hidden=true;let selectionHint=null;let protocolInfo='';controls();$('disconnect').textContent='لغو اتصال';const messages={legacy:'مدل قدیمی شناسایی شد؛ روبیک را چند لحظه ثابت نگه دار. نیازی به MAC نیست.',gatt:'در حال برقراری ارتباط بلوتوث؛ روبیک را نزدیک کامپیوتر نگه دار…',services:'سرویس‌های بلوتوث خوانده شد…',reconnect:'سرویس دریافت نشد؛ یک بار اتصال را دوباره برقرار می‌کنم…',select:'دو سه حرکت معمولی به روبیک بده، سپس آن را در پنجره بلوتوث Chrome انتخاب کن.',advertisement:'در حال خواندن اطلاعات بلوتوث؛ چند حرکت به روبیک بده…',prepare:'در حال تشخیص سرویس بلوتوث روبیک…',protocol:'پروتکل شناسایی شد؛ آماده دریافت حرکت‌ها…',verify:'در حال تأیید وضعیت واقعی روبیک…'};try{const result=await connectCube({manualMac:mac,signal:controller.signal,onProgress:(stage,data={})=>{if(attempt!==connectAttempt)return;connectStage=stage;clearTimeout(selectionHint);if(stage==='select')selectionHint=setTimeout(()=>{if(attempt===connectAttempt&&busy&&connectStage==='select'){notice('اگر پنجره انتخاب دستگاه باز نشده، «لغو اتصال» را بزن. اگر درخواست Chrome گیر کرده است، از دکمه تازه‌سازی استفاده کن.',true);$('reloadconnection').hidden=false;}},8000);if(data.uuid)protocolInfo=' | '+(data.protocol?'پروتکل: '+data.protocol+' | ':'')+'UUID: '+data.uuid;if(stage==='turns')notice('برای شناسایی، یک وجه روبیک را ۵ بار آهسته بچرخان. حرکت دریافت‌شده: '+fa.format(data.count)+' از ۵');else if(stage==='search')notice('در حال بازیابی اتصال روی همین دستگاه؛ لطفاً صفحه را باز نگه دار. بررسی‌شده: '+fa.format(data.checked||0)+' گزینه. برای توقف «لغو اتصال» را بزن.');else notice(messages[stage]||stage);$('phase').textContent=stage==='turns'?'منتظر ۵ حرکت':stage==='search'?'بازیابی اتصال':'در حال اتصال';$('diagnostic').textContent='مرحله: '+stage+(data.name?' | دستگاه: '+data.name:'')+(data.operation?' | عملیات: '+data.operation:'')+(data.checked?' | بررسی‌شده: '+data.checked:'')+protocolInfo;}});if(attempt!==connectAttempt){await result.connection.disconnect().catch(()=>{});return;}connectionPaused=false;conn=result.connection;subscription=conn.events$.subscribe({next:event,error:()=>{cancel();cube=null;draw();controls();notice('دریافت داده متوقف شد. دوباره وصل کن.',true)}});event(result.state);conn.sendCubeCommand({type:'REQUEST_BATTERY'}).catch(()=>{});notice('اتصال و دریافت وضعیت معتبر تأیید شد. نمایش را با روبیکت مقایسه کن.');$('diagnostic').textContent='نسخه اتصال ۱۵ | دستگاه: '+conn.deviceName+' | وضعیت معتبر دریافت شد';}catch(e){if(attempt!==connectAttempt)return;conn=null;cube=null;draw();if(e.name==='PickerPendingError'||e.operation==='select')$('reloadconnection').hidden=false;notice(e.name==='NotFoundError'||e.name==='AbortError'?'اتصال لغو شد.':'اتصال کامل نشد: '+e.message,true);$('diagnostic').textContent+=' | '+e.name+': '+e.message;}finally{clearTimeout(selectionHint);if(attempt===connectAttempt){busy=false;connectAbort=null;connectStage=null;$('disconnect').textContent='قطع اتصال';controls()}}};
$('disconnect').onclick=async()=>{if(busy){const selecting=connectStage==='select';connectAttempt++;const controller=connectAbort;connectAbort=null;connectStage=null;busy=false;controller?.abort();$('disconnect').textContent='قطع اتصال';controls();if(selecting)$('reloadconnection').hidden=false;notice(selecting?'تلاش اتصال لغو شد. اگر پنجره بلوتوث Chrome باز مانده، آن را هم ببند؛ اگر پنجره‌ای نیست و دوباره باز نشد، صفحه را تازه‌سازی کن.':'تلاش اتصال لغو شد.');return}cancel();if(conn)await conn.disconnect();subscription?.unsubscribe();subscription=null;conn=null;cube=null;draw();controls()};
$('sync').onclick=async()=>{if(armed)cancel();try{await conn.sendCubeCommand({type:'REQUEST_FACELETS'});notice('درخواست خواندن وضعیت ارسال شد. نمایش مکعب را بررسی کن.')}catch(e){notice('خواندن وضعیت انجام نشد: '+e.message,true)}};
$('reset').onclick=async()=>{if(!confirm('آیا هر شش وجه روبیک واقعی کاملاً حل شده است؟'))return;try{await conn.sendCubeCommand({type:'REQUEST_RESET'});cube=new Cube();draw();controls();notice('روبیک حل‌شده همگام شد. حالا می‌توانی آن را به‌هم بریزی.')}catch(e){notice('همگام‌سازی انجام نشد: '+e.message,true)}};
$('arm').onclick=()=>{if(!cube||cube.asString()===solved){notice('قبل از آماده‌شدن برای حل، روبیک را به‌هم بریز.',true);return}armed=true;moveCount=0;$('moves').textContent='۰';$('clock').textContent='0.00';controls();notice('با اولین حرکت، زمان شروع می‌شود؛ با حل کامل متوقف می‌شود.')};$('cancel').onclick=()=>{cancel();notice('حل لغو شد و رکوردی ذخیره نشد.')};
$('robot').onclick=async()=>{if(!navigator.bluetooth){notice('شناسایی ربات به Chrome و بلوتوث وب نیاز دارد.',true);return}try{const d=await navigator.bluetooth.requestDevice({acceptAllDevices:true});$('robotInfo').textContent='نام بلوتوث: '+(d.name||'نام مشخص نیست')+' — این نام یا عکس ربات را در گفتگو بفرست. هیچ فرمان حرکتی ارسال نشده است.'}catch(e){notice(e.name==='NotFoundError'?'انتخاب ربات لغو شد.':'شناسایی انجام نشد: '+e.message,true)}};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,solves:records},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='gan-solves.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function tick(){if(running)$('clock').textContent=((performance.now()-start)/1000).toFixed(2);requestAnimationFrame(tick)}draw();renderRecords();controls();tick();if(!navigator.bluetooth)notice('این صفحه را مستقیماً در Chrome باز کن؛ مرورگر فعلی اتصال بلوتوث ندارد.',true);

$('forget').onclick=async()=>{try{if(await forgetLastDevice())notice('مجوز همین روبیک برای این سایت حذف شد. حالا اتصال روبیک را بزن و دوباره دستگاه را انتخاب کن.');else notice('ابتدا یک بار اتصال روبیک را بزن و دستگاه را انتخاب کن.')}catch(e){notice(e.message,true)}};

$('linktest').onclick=async()=>{if(!conn?.testIdleLink){notice('اول روبیک را وصل کن؛ این آزمایش برای مدل قدیمی دستگاه تو است.',true);return}const button=$('linktest');button.disabled=true;const began=Date.now();const original=button.textContent;const countdown=setInterval(()=>{button.textContent='زمان باقی‌مانده: '+fa.format(Math.max(0,60-Math.floor((Date.now()-began)/1000)))+' ثانیه';},1000);try{const result=await conn.testIdleLink();if(result.cancelled)notice('آزمایش لغو شد.');else notice(result.survived?'آزمایش: ۶۰ ثانیه بدون خواندن داده، اتصال باقی ماند. نتیجه و گزارش اتصال را در گفتگو بفرست.':'آزمایش: حتی بدون خواندن داده، ارتباط بسته شد. گزارش اتصال را در گفتگو بفرست.');}catch(e){notice(e.message,true)}finally{clearInterval(countdown);button.textContent=original;button.disabled=false}};

$('motiontest').onclick=async()=>{
 const output=$('motionresult'),button=$('motiontest'),label=button.textContent;
 output.value='کلیک دریافت شد؛ بررسی اتصال…';
 if(!conn){output.value='روبیک متصل نیست. ابتدا دکمه اتصال روبیک را بزن.';return}
 if(connectionPaused){output.value='اتصال در حال بازیابی است. پس از نمایش نام روبیک دوباره آزمایش را بزن.';return}
 if(typeof conn.probeMotion!=='function'){output.value='کد اتصال قدیمی در مرورگر مانده است. صفحه را با ⌘⇧R تازه‌سازی و دوباره وصل کن.';return}
 const target=conn;let watchdog;button.disabled=true;$('linktest').disabled=true;button.textContent='در حال آماده‌سازی آزمایش…';
 output.value='آزمایش شروع شد. وجه راست را هر ثانیه ۹۰ درجه، یک بار رفت و یک بار برگشت بچرخان.';
 try{const result=await Promise.race([target.probeMotion(),new Promise((resolve,reject)=>{watchdog=setTimeout(()=>{reject(new Error('آزمایش در ۲۵ ثانیه پاسخ نداد. اتصال متوقف شد؛ دوباره وصل کن.'));target.disconnect().catch(()=>{});},25000)})]);output.value=JSON.stringify(result.summary||{error:result.error||'آزمایش بدون نتیجه پایان یافت.'},null,2);notice('آزمایش حرکت پایان یافت. متن کادر «نتیجه آزمایش حرکت» را بفرست.');}
 catch(e){output.value='آزمایش اجرا نشد: '+e.message;notice(e.message,true)}
 finally{clearTimeout(watchdog);button.disabled=false;$('linktest').disabled=false;button.textContent=label}
};

$('reloadconnection').onclick=()=>{if(conn||busy){notice('ابتدا اتصال یا تلاش جاری را قطع کن، سپس صفحه را تازه‌سازی کن.',true);return;}location.reload()};
